function chooseScan({ pages, matching, randomPageCost }){
  const seqCost = pages;
  const indexCost = matching * randomPageCost;
  return seqCost < indexCost ? 'index' : 'seq';
}

tasks.verify:
const selective = chooseScan({ pages:10000, matching:2000, randomPageCost:4 });
const broad = chooseScan({ pages:10000, matching:450000, randomPageCost:4 });
const ok = selective === 'index' && broad === 'seq';
console.log(ok ? 'PASS' : 'FAIL selective='+selective+' broad='+broad);

